content.query:
// SLO definition for this demo: 95% of requests should complete under 500ms.
// Adjust the 500 / 95 constants below to match a real SLO target.
AppRequests
| where cloud_RoleName == '{Service}'
| where timestamp {TimeRange}
| summarize Total = count(), UnderTarget = countif(duration < 500)
| project ["SLO: % of requests under 500ms"] = round(100.0 * UnderTarget / Total, 2)
